def hlp_source_under(folder):
    """
    this function finds all the python packages under a folder and
    write the 'packages' and 'package_dir' entries for a python setup.py
    script
    """
    # TODO: make it work for all folder, not just 'src'
    packages = []
    package_dir = {}
    for root, dirs, files in os.walk(folder):
        if not root.startswith("."):
            if "__init__.py" in files:
                if not root.startswith("src"):
                    packages.append(root.replace(os.path.sep, "."))
                else:
                    packages.append(root.replace(os.path.sep, ".")[4:])
            elif root != folder:
                if not root.startswith("src"):
                    package_dir[root.replace(os.path.sep, ".")] = root.replace(os.path.sep, ".")
                else:
                    package_dir[root.replace(os.path.sep, ".")[4:]] = root.replace(os.path.sep, ".")[4:]

    return packages, package_dir

