def hlp_add_entry_points(entry_points, name, value):
    """
    this function adds an entry point to the entry points dictionary
    :param entry_points: dictionary of entry points
    :param name: name of the entry point
    :param value: value of the entry point
    :return: updated entry points
    """
    if entry_points is None:
        entry_points = {}
    if name not in entry_points:
        entry_points[name] = []
    entry_points[name].append(value)
    return entry_points


def hlp_get_setup_data(setup_data, attr_name, value):
    """
    this function adds an attribute to the setup data
    :param setup_data: dictionary of setup data
    :param attr_name: name of the attribute to add
    :param value: value of the attribute to add
    :return: updated setup data
    """
    if setup_data is None:
        setup_data = {}
    setup_data[attr_name] = value
    return setup_data


